function batchMint(
    ITokenMinter nftMinter,
    IERC20 paymentToken,
    uint256 dispatcherIndex,
    uint256 count,
    address recipient,
    uint256 paymentAmount
) external returns (uint256 totalPaid) {
    // ...
    paymentToken.safeTransferFrom(msg.sender, address(this), paymentAmount);
    paymentToken.forceApprove(address(nftMinter), type(uint256).max);

    for (uint256 i; i < count; ++i) {
        nftMinter.mint(address(paymentToken), dispatcherIndex, recipient);
    }
    // No max-price, no per-mint ceiling, no expected-starting-price assertion

paymentToken.forceApprove(address(nftMinter), type(uint256).max);

for (uint256 i; i < count; ++i) {
    nftMinter.mint(address(paymentToken), dispatcherIndex, recipient);
}

paymentToken.forceApprove(address(nftMinter), 0);

if (recipient == address(0)) revert BatchMint__ZeroRecipient();
// ...
for (uint256 i; i < count; ++i) {
    nftMinter.mint(address(paymentToken), dispatcherIndex, recipient);
}

